import React from 'react';
import { motion } from 'framer-motion';
import { BookOpen, Trophy, Cpu, Award } from 'lucide-react';

const About = () => {
  const skills = [
    { name: "Machine Learning", level: "90%" },
    { name: "React.js & Frontend", level: "85%" },
    { name: "Python & FastAPI", level: "88%" },
    { name: "C++ & Data Structures", level: "92%" },
    { name: "SQL & Databases", level: "80%" },
  ];

  const stats = [
    { label: "CGPA", value: "7.65", icon: <BookOpen size={20}/> },
    { label: "Projects", value: "10+", icon: <Cpu size={20}/> },
    { label: "LeetCode", value: "150+", icon: <Trophy size={20}/> },
    { label: "Certificates", value: "5+", icon: <Award size={20}/> },
  ];

  return (
    <section id="about" className="py-24 px-10 bg-white">
      <div className="container mx-auto max-w-6xl">
        <h2 className="text-5xl font-black tracking-tighter mb-16 uppercase italic">
          About <span className="text-blue-600">Me</span>
        </h2>

        <div className="grid md:grid-cols-2 gap-10 mb-10">
          {/* Left Side: Bio Card */}
          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            className="p-10 bg-gray-50 rounded-[2.5rem] border border-gray-100 shadow-sm"
          >
            <h3 className="text-3xl font-bold mb-6">Hello There!</h3>
            <p className="text-gray-600 leading-relaxed text-lg mb-6">
              I am a passionate AI/ML Engineer and Full Stack Developer currently pursuing my 
              B.Tech at <strong>Lovely Professional University</strong>[cite: 42, 43]. I specialize in 
              turning complex security vulnerabilities into elegant automated solutions[cite: 11, 37].
            </p>
            <p className="text-gray-600 leading-relaxed text-lg">
              When I'm not coding, I'm solving DSA problems or optimizing backend architectures 
              using <strong>FastAPI</strong> and <strong>React</strong>[cite: 7, 39].
            </p>
          </motion.div>

          {/* Right Side: Core Competencies */}
          <motion.div 
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            className="p-10 bg-gray-900 text-white rounded-[2.5rem] shadow-2xl"
          >
            <h3 className="text-2xl font-bold mb-8 text-blue-400 uppercase tracking-widest">Core Competencies</h3>
            <div className="space-y-6">
              {skills.map((skill, index) => (
                <div key={index} className="space-y-2">
                  <div className="flex justify-between text-sm font-bold">
                    <span>{skill.name}</span>
                    <span className="text-blue-400">{skill.level}</span>
                  </div>
                  <div className="w-full bg-white/10 h-2 rounded-full overflow-hidden">
                    <motion.div 
                      initial={{ width: 0 }}
                      whileInView={{ width: skill.level }}
                      transition={{ duration: 1, delay: 0.5 }}
                      className="bg-blue-500 h-full rounded-full"
                    />
                  </div>
                </div>
              ))}
            </div>
          </motion.div>
        </div>

        {/* Bottom Stats Grid */}
        <div className="grid grid-cols-2 md:grid-cols-4 gap-6">
          {stats.map((stat, index) => (
            <motion.div 
              key={index}
              whileHover={{ y: -5 }}
              className="p-8 bg-white border-2 border-gray-100 rounded-3xl text-center shadow-sm hover:shadow-md transition-all"
            >
              <div className="text-blue-600 mb-3 flex justify-center">{stat.icon}</div>
              <h4 className="text-3xl font-black mb-1">{stat.value}</h4>
              <p className="text-gray-400 text-xs font-bold uppercase tracking-widest">{stat.label}</p>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default About;
